G=load()

def transform(g):
    h,w=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    bar=None; orient=None
    for j in range(w):
        if all(g[i][j]!=bg for i in range(h)): bar=j; orient='v'
    for i in range(h):
        if all(g[i][j]!=bg for j in range(w)): bar=i; orient='h'
    barcol = g[0][bar] if orient=='v' else g[bar][0]
    shape=[(i,j) for i in range(h) for j in range(w) if g[i][j]!=bg and g[i][j]!=barcol]
    top=min(i for i,j in shape); bot=max(i for i,j in shape)
    left=min(j for i,j in shape); right=max(j for i,j in shape)
    new=[r[:] for r in g]
    def free(c):
        return all(g[i][c]==bg for i in range(h))
    def freer(r):
        return all(g[r][j]==bg for j in range(w))
    if orient=='v':
        c = right+1 if (bar>right and right+1<w and free(right+1)) else (left-1 if bar>right else left-1 if (left-1>=0 and free(left-1)) else right+1)
        for i in range(h): new[i][c]=8
    else:
        r = bot+1 if (bar>bot and bot+1<h and freer(bot+1)) else (top-1 if bar>bot else top-1 if (top-1>=0 and freer(top-1)) else bot+1)
        for j in range(w): new[r][j]=8
    return new

